  function injectScriptText(code, sourceName) {
    var s = document.createElement("script");
    s.type = "text/javascript";
    s.text = code + "\n//# sourceURL=" + sourceName;
    document.head.appendChild(s);
  }

  function loadScriptOnce(src, globalName, callback) {
    if (globalName && window[globalName]) {
      callback();
      return;
    }

    var existing = Array.prototype.slice.call(document.scripts).find(function (script) {
      return script.src && script.src.indexOf(src) === 0;
    });

    if (existing) {
      existing.addEventListener("load", callback, { once: true });
      if (globalName && window[globalName]) callback();
      return;
    }

    var script = document.createElement("script");
    script.src = src;
    script.async = true;
    script.onload = callback;
    script.onerror = function () {
      console.error("USAVET.AI dashboard dependency failed:", src);
      callback();
    };
    document.head.appendChild(script);
  }


